import * as React from "react";
import {
  Page,
  BlockStack,
  Banner,
} from "@xco-agency/corex-ui";
import {
  INITIAL_USAGE,
  MOCK_INVOICES,
  MOCK_PAYMENT_METHOD,
  PLAN_TIERS,
} from "../constants";
import { ActivePlanHeroCard } from "../partials/ActivePlanHeroCard";
import { UsageMetersCard } from "../partials/UsageMetersCard";
import { PlanSwitchComparisonCard } from "../partials/PlanSwitchComparisonCard";
import { InvoiceHistoryCard } from "../partials/InvoiceHistoryCard";
import type {
  BillingIntervalType,
  InvoiceItemType,
  PlanTierType,
  SubscriptionStateType,
} from "../types";

export function SubscriptionManagementExample() {
  const [state, setState] = React.useState<SubscriptionStateType>({
    currentPlanId: "plan-growth",
    billingInterval: "monthly",
    nextBillingDate: "Oct 01, 2026",
    paymentMethod: MOCK_PAYMENT_METHOD,
    usage: INITIAL_USAGE,
    invoices: MOCK_INVOICES,
  });

  const [notification, setNotification] = React.useState<string | null>(null);

  const currentPlan: PlanTierType =
    PLAN_TIERS.find((p) => p.id === state.currentPlanId) ?? PLAN_TIERS[1]!;

  const handleChangeInterval = (interval: BillingIntervalType) => {
    setState((prev) => ({ ...prev, billingInterval: interval }));
    setNotification(
      `Switched to ${interval} billing cycle. ${interval === "annual" ? "20% annual savings applied!" : ""}`,
    );
  };

  const handleSelectPlan = (newPlan: PlanTierType) => {
    setState((prev) => ({ ...prev, currentPlanId: newPlan.id }));
    setNotification(
      `Successfully switched to the ${newPlan.name} plan. Prorated credits have been calculated for your remaining billing cycle.`,
    );
  };

  const handleDownloadInvoice = (invoice: InvoiceItemType) => {
    setNotification(
      `Downloading PDF receipt for invoice ${invoice.invoiceNumber} ($${invoice.amount.toFixed(2)})...`,
    );
  };

  const handleUpdatePayment = () => {
    setNotification(
      "Directing to secure Shopify Billing payment method verification...",
    );
  };

  return (
    <Page
      heading="Subscription, Quotas & Billing"
      subheading="Manage your app tier subscription, track real-time resource quota meters, and review billing invoices."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {notification && (
          <Banner
            tone="success"
            title={notification}
            onDismiss={() => setNotification(null)}
          />
        )}

        {/* Current Active Subscription Banner & Rates */}
        <ActivePlanHeroCard
          currentPlan={currentPlan}
          billingInterval={state.billingInterval}
          nextBillingDate={state.nextBillingDate}
          paymentMethod={state.paymentMethod}
          onChangeInterval={handleChangeInterval}
          onUpdatePayment={handleUpdatePayment}
        />

        {/* Resource Usage Meters */}
        <UsageMetersCard
          usage={state.usage}
          cycleEndDate={state.nextBillingDate}
        />

        {/* Plan Comparison & Upgrades */}
        <PlanSwitchComparisonCard
          currentPlanId={state.currentPlanId}
          billingInterval={state.billingInterval}
          onSelectPlan={handleSelectPlan}
        />

        {/* Invoices History Table */}
        <InvoiceHistoryCard
          invoices={state.invoices}
          onDownloadInvoice={handleDownloadInvoice}
        />
      </BlockStack>
    </Page>
  );
}

export { SubscriptionManagementExample } from "./examples/SubscriptionManagementExample";
export type {
  BillingIntervalType,
  InvoiceItemType,
  InvoiceStatusType,
  PaymentMethodType,
  PlanLimitsType,
  PlanTierType,
  SubscriptionStateType,
  UsageQuotaType,
} from "./types";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import type {
  BillingIntervalType,
  PaymentMethodType,
  PlanTierType,
} from "../types";

type ActivePlanHeroCardPropsType = {
  currentPlan: PlanTierType;
  billingInterval: BillingIntervalType;
  nextBillingDate: string;
  paymentMethod: PaymentMethodType;
  onChangeInterval: (interval: BillingIntervalType) => void;
  onUpdatePayment: () => void;
};

export function ActivePlanHeroCard({
  currentPlan,
  billingInterval,
  nextBillingDate,
  paymentMethod,
  onChangeInterval,
  onUpdatePayment,
}: ActivePlanHeroCardPropsType) {
  const currentPrice =
    billingInterval === "monthly"
      ? currentPlan.monthlyPrice
      : Math.round(currentPlan.annualPrice / 12);

  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <InlineStack gap="small-200" alignItems="center">
              <Text as="h2" fontWeight="bold">
                Current Subscription: {currentPlan.name} Plan
              </Text>
              <Badge tone="success">Active Status</Badge>
              {billingInterval === "annual" && (
                <Badge tone="info">Annual 20% Discount</Badge>
              )}
            </InlineStack>
            <Text color="subdued" variant="small">
              {currentPlan.description}
            </Text>
          </BlockStack>

          {/* Billing Interval Segmented Switch using Corex UI ButtonGroup */}
          <ButtonGroup variant="segmented">
            <Button
              variant={billingInterval === "monthly" ? "primary" : "secondary"}
              onClick={() => onChangeInterval("monthly")}
            >
              Monthly
            </Button>
            <Button
              variant={billingInterval === "annual" ? "primary" : "secondary"}
              onClick={() => onChangeInterval("annual")}
            >
              Annual (Save 20%)
            </Button>
          </ButtonGroup>
        </InlineStack>

        <Divider />

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: "var(--p-space-400, 16px)",
          }}
        >
          {/* Rate Card */}
          <Box padding="small-300" background="subdued" borderRadius="base">
            <BlockStack gap="small-500">
              <Text color="subdued" variant="small">
                Recurring Rate
              </Text>
              <InlineStack gap="small-200" alignItems="baseline">
                <Text fontWeight="bold" variant="large">
                  ${currentPrice}
                </Text>
                <Text color="subdued" variant="small">
                  / month ({billingInterval})
                </Text>
              </InlineStack>
            </BlockStack>
          </Box>

          {/* Next Invoice Date */}
          <Box padding="small-300" background="subdued" borderRadius="base">
            <BlockStack gap="small-500">
              <Text color="subdued" variant="small">
                Next Scheduled Renewal
              </Text>
              <Text fontWeight="semibold" variant="small">
                {nextBillingDate}
              </Text>
              <Text color="subdued" variant="small">
                Automatic charge via Shopify Merchant Billing
              </Text>
            </BlockStack>
          </Box>

          {/* Payment Method */}
          <Box padding="small-300" background="subdued" borderRadius="base">
            <BlockStack gap="small-500">
              <InlineStack justifyContent="space-between" alignItems="center">
                <Text color="subdued" variant="small">
                  Card on File
                </Text>
                <Button variant="tertiary" onClick={onUpdatePayment}>
                  Update
                </Button>
              </InlineStack>
              <Text fontWeight="semibold" variant="small">
                {paymentMethod.brand} ending in {paymentMethod.last4}
              </Text>
              <Text color="subdued" variant="small">
                Expires {paymentMethod.expMonth}/{paymentMethod.expYear}
              </Text>
            </BlockStack>
          </Box>
        </div>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import type { InvoiceItemType } from "../types";

type InvoiceHistoryCardPropsType = {
  invoices: InvoiceItemType[];
  onDownloadInvoice: (invoice: InvoiceItemType) => void;
};

export function InvoiceHistoryCard({
  invoices,
  onDownloadInvoice,
}: InvoiceHistoryCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Billing History & Tax Receipts
            </Text>
            <Text color="subdued" variant="bodySm">
              Download GST/VAT compliant PDF receipts for your company accounting records.
            </Text>
          </BlockStack>
          <Badge tone="neutral">{invoices.length} Recent Invoices</Badge>
        </InlineStack>

        <Divider />

        <BlockStack gap="small-200">
          {invoices.map((inv) => {
            const statusTone =
              inv.status === "paid"
                ? "success"
                : inv.status === "pending"
                  ? "caution"
                  : "critical";

            return (
              <Box
                key={inv.id}
                padding="small"
                background="base"
                borderRadius="base"
                borderWidth="small-100"
                borderColor="subdued"
                borderStyle="solid"
              >
                <InlineStack justifyContent="space-between" alignItems="center">
                  <InlineStack gap="base" alignItems="center">
                    <div
                      style={{
                        width: "36px",
                        height: "36px",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        backgroundColor: "var(--p-color-bg-subdued, #f6f6f7)",
                        borderRadius: "var(--p-border-radius-100, 6px)",
                        fontSize: "16px",
                      }}
                    >
                      📄
                    </div>

                    <BlockStack gap="small-500">
                      <InlineStack gap="small-200" alignItems="center">
                        <Text fontWeight="semibold" variant="bodySm">
                          {inv.invoiceNumber}
                        </Text>
                        <Badge tone={statusTone}>
                          {inv.status.toUpperCase()}
                        </Badge>
                      </InlineStack>
                      <Text color="subdued" variant="bodySm">
                        Billed on {inv.date} · Automatic charge
                      </Text>
                    </BlockStack>
                  </InlineStack>

                  <InlineStack gap="base" alignItems="center">
                    <Text fontWeight="bold" variant="bodySm">
                      ${inv.amount.toFixed(2)} {inv.currency}
                    </Text>

                    <Button
                      variant="secondary"
                      onClick={() => onDownloadInvoice(inv)}
                    >
                      Download PDF
                    </Button>
                  </InlineStack>
                </InlineStack>
              </Box>
            );
          })}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import { PLAN_TIERS } from "../constants";
import type { BillingIntervalType, PlanTierType } from "../types";

type PlanSwitchComparisonCardPropsType = {
  currentPlanId: string;
  billingInterval: BillingIntervalType;
  onSelectPlan: (plan: PlanTierType) => void;
};

export function PlanSwitchComparisonCard({
  currentPlanId,
  billingInterval,
  onSelectPlan,
}: PlanSwitchComparisonCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Available Subscription Tiers
            </Text>
            <Text color="subdued" variant="bodySm">
              Upgrade or downgrade your plan at any time. Prorated credits are automatically applied.
            </Text>
          </BlockStack>
          <Badge tone="info">Instant Prorated Billing</Badge>
        </InlineStack>

        <Divider />

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: "var(--p-space-400, 16px)",
            alignItems: "stretch",
          }}
        >
          {PLAN_TIERS.map((tier) => {
            const isCurrent = tier.id === currentPlanId;
            const price =
              billingInterval === "monthly"
                ? tier.monthlyPrice
                : Math.round(tier.annualPrice / 12);

            return (
              <div
                key={tier.id}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                  position: "relative",
                  padding: "var(--p-space-400, 16px)",
                  backgroundColor: "var(--p-color-bg-surface, #ffffff)",
                  borderRadius: "var(--p-border-radius-200, 8px)",
                  border: isCurrent
                    ? "1px solid var(--p-color-border-primary, #008060)"
                    : "1px solid var(--p-color-border-subdued, #e1e3e5)",
                  boxShadow: isCurrent
                    ? "0 0 0 1px var(--p-color-border-primary, #008060)"
                    : "none",
                }}
              >
                <BlockStack gap="base">
                  <InlineStack justifyContent="space-between" alignItems="center">
                    <Text fontWeight="bold" variant="large">
                      {tier.name}
                    </Text>
                    {tier.badge && (
                      <Badge tone={isCurrent ? "success" : "info"}>
                        {tier.badge}
                      </Badge>
                    )}
                  </InlineStack>

                  <InlineStack gap="small-200" alignItems="baseline">
                    <Text fontWeight="bold" variant="large">
                      ${price}
                    </Text>
                    <Text color="subdued" variant="bodySm">
                      / month ({billingInterval})
                    </Text>
                  </InlineStack>

                  <Text variant="bodySm" color="subdued">
                    {tier.description}
                  </Text>

                  <Divider />

                  <BlockStack gap="small-300">
                    <Text fontWeight="semibold" variant="bodySm">
                      Included features:
                    </Text>
                    {tier.features.map((feat, idx) => (
                      <div
                        key={idx}
                        style={{
                          display: "flex",
                          gap: "var(--p-space-200, 8px)",
                          alignItems: "flex-start",
                        }}
                      >
                        <span
                          style={{
                            color: "var(--p-color-text-success, #008060)",
                            fontWeight: 700,
                            lineHeight: "1.2rem",
                          }}
                        >
                          ✓
                        </span>
                        <Text variant="bodySm">{feat}</Text>
                      </div>
                    ))}
                  </BlockStack>
                </BlockStack>

                <div style={{ marginTop: "var(--p-space-500, 20px)" }}>
                  {isCurrent ? (
                    <Button variant="secondary" disabled>
                      Active Plan
                    </Button>
                  ) : (
                    <Button
                      variant={tier.id === "plan-enterprise" ? "primary" : "secondary"}
                      onClick={() => onSelectPlan(tier)}
                    >
                      {tier.monthlyPrice >
                      (PLAN_TIERS.find((p) => p.id === currentPlanId)?.monthlyPrice ?? 0)
                        ? "Upgrade to " + tier.name
                        : "Downgrade to " + tier.name}
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  ProgressBar,
  Divider,
} from "@xco-agency/corex-ui";
import type { UsageQuotaType } from "../types";

type UsageMetersCardPropsType = {
  usage: UsageQuotaType[];
  cycleEndDate: string;
};

export function UsageMetersCard({
  usage,
  cycleEndDate,
}: UsageMetersCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Current Billing Cycle Resource Quotas
            </Text>
            <Text color="subdued" variant="bodySm">
              Real-time consumption meters. Quota resets on {cycleEndDate}.
            </Text>
          </BlockStack>
          <Badge tone="neutral">Monthly Usage Metering</Badge>
        </InlineStack>

        <Divider />

        <BlockStack gap="base">
          {usage.map((quota) => {
            const percentage = Math.round((quota.used / quota.total) * 100);
            const isNearLimit = percentage >= quota.warningThreshold;
            const tone =
              percentage >= 90
                ? "critical"
                : percentage >= quota.warningThreshold
                  ? "caution"
                  : "success";

            return (
              <BlockStack key={quota.resource} gap="small-400">
                <InlineStack justifyContent="space-between" alignItems="center">
                  <InlineStack gap="small-200" alignItems="center">
                    <Text fontWeight="semibold" variant="bodySm">
                      {quota.resource}
                    </Text>
                    {isNearLimit && (
                      <Badge tone={tone}>
                        {percentage >= 90 ? "High Usage Alert" : "Approaching Limit"}
                      </Badge>
                    )}
                  </InlineStack>
                  <Text variant="bodySm" fontWeight="medium">
                    {quota.used.toLocaleString()} / {quota.total.toLocaleString()} {quota.unit} ({percentage}%)
                  </Text>
                </InlineStack>

                <ProgressBar
                  progress={percentage}
                  tone={tone}
                  size="base"
                />
              </BlockStack>
            );
          })}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

export type BillingIntervalType = "monthly" | "annual";

export type PlanLimitsType = {
  orders: number;
  seats: number;
  apiCalls: number;
};

export type PlanTierType = {
  id: string;
  name: string;
  monthlyPrice: number;
  annualPrice: number;
  description: string;
  badge?: string;
  isCurrent?: boolean;
  features: string[];
  limits: PlanLimitsType;
};

export type UsageQuotaType = {
  resource: string;
  used: number;
  total: number;
  unit: string;
  warningThreshold: number;
};

export type InvoiceStatusType = "paid" | "pending" | "failed";

export type InvoiceItemType = {
  id: string;
  invoiceNumber: string;
  date: string;
  amount: number;
  currency: string;
  status: InvoiceStatusType;
  downloadUrl: string;
};

export type PaymentMethodType = {
  brand: string;
  last4: string;
  expMonth: number;
  expYear: number;
};

export type SubscriptionStateType = {
  currentPlanId: string;
  billingInterval: BillingIntervalType;
  nextBillingDate: string;
  paymentMethod: PaymentMethodType;
  usage: UsageQuotaType[];
  invoices: InvoiceItemType[];
};
